import { useEffect, useState } from 'react';
import { getProducts, getAllOrders } from '../../services/api';
import './AdminDashboard.css';

export default function AdminDashboard() {
  const [stats, setStats] = useState({ products: 0, orders: 0, revenue: 0, pending: 0 });

  useEffect(() => {
    Promise.all([getProducts({ limit: 100 }), getAllOrders()]).then(([p, o]) => {
      const orders = o.data;
      setStats({
        products: p.data.total,
        orders: orders.length,
        revenue: orders.reduce((s, o) => s + o.totalAmount, 0),
        pending: orders.filter((o) => o.status === 'pending').length,
      });
    });
  }, []);

  const cards = [
    { label: 'Total Products', value: stats.products, icon: '👗', color: '#b5833a' },
    { label: 'Total Orders', value: stats.orders, icon: '📦', color: '#2980b9' },
    { label: 'Revenue', value: `₹${stats.revenue.toLocaleString()}`, icon: '💰', color: '#27ae60' },
    { label: 'Pending Orders', value: stats.pending, icon: '⏳', color: '#e67e22' },
  ];

  return (
    <div className="admin-dashboard">
      <h1 className="admin-page-title">Dashboard</h1>
      <div className="stat-grid">
        {cards.map((c) => (
          <div className="stat-card" key={c.label}>
            <div className="stat-icon" style={{ background: c.color + '22', color: c.color }}>{c.icon}</div>
            <div>
              <div className="stat-value">{c.value}</div>
              <div className="stat-label">{c.label}</div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
